struct MaxFlow{
	int head[N], v[M], nxt[M], cap[M], flow[M], e;
	int dist[N], cur[N];
	int s, t;
	void init(){
		memset(head, -1, sizeof head); e = 0;
	}
	void addEdge(int u, int v, int c){
		vv[e] = v, nxt[e] = head[u], cap[e] = c, flow[e] = 0, head[u] = e++;
		vv[e] = u, nxt[e] = head[v], cap[e] = 0, flow[e] = 0, head[v] = e++;
	}
	bool bfs(){
	   	memset(dist, -1, sizeof dist);
   	   	dist[s] = 0;
		queue<int> q;
		q.push(s);
		while(!q.empty()){
			int u = q.front(); q.pop();
			for(int i = head[u]; ~i; i = nxt[i]){
				int v = v[i];
				if(dist[v] == -1 && cap[i] > flow[i]){
					dist[v] = dist[u] + 1;
					q.push(v);
				}
			}
		}
		return dist[t] != -1;
	}
	int dfs(int u, int a){
		if(u == t || a == 0) return a;
		int ret = 0, f;
		for(int &i = cur[u]; ~i; i = nxt[i]){
			int v = v[i];
			if(dist[v] == dist[u] + 1 && (f = dfs(v, min(a, cap[i] - flow[i]))) > 0){
				a -= f;
				ret += f;
				flow[i] += f;
				flow[i^1] -=f;
				if(a == 0) break;
			}
		}
		return ret;
	}
	int maxFlow(int _s, int _t){
		s = _s, t = _t;
		int ret = 0;
		while(bfs()){
			memcpy(cur, head, sizeof head);
			ret += dfs(s, inf);
		}
		return ret;
	}
}mf;
int directions[4][2] = {-1, 0, 0, 1, 1, 0, 0, -1};
